package com.aistock.prediction.comparison;
import com.aistock.common.*;import com.aistock.prediction.modelcatalog.ModelRecords.Actor;import com.fasterxml.jackson.core.JsonParser;import com.fasterxml.jackson.databind.*;import jakarta.servlet.http.HttpServletRequest;import org.springframework.http.*;import org.springframework.security.core.Authentication;import org.springframework.web.bind.annotation.*;import java.time.*;import java.util.*;import static com.aistock.prediction.comparison.ComparisonRecords.*;
@RestController public class ComparisonController {
 private final ComparisonService service;private final ObjectMapper mapper;
 public ComparisonController(ComparisonService service,ObjectMapper mapper){this.service=service;this.mapper=mapper.copy().enable(JsonParser.Feature.STRICT_DUPLICATE_DETECTION).enable(DeserializationFeature.FAIL_ON_TRAILING_TOKENS);}
 @GetMapping("/api/v1/comparisons/options") public ApiResponse<?> options(Authentication auth,HttpServletRequest req){owner(auth);query(req,Set.of("ids","period"));String ids=req.getParameter("ids"),period=req.getParameter("period");if(ids==null||ids.length()>32||period==null||!Set.of("3M","6M","1Y").contains(period))throw ComparisonErrors.invalid();var stocks=List.of(ids.split(",",-1));if(stocks.size()<2||stocks.size()>3||new HashSet<>(stocks).size()!=stocks.size()||stocks.stream().anyMatch(s->!s.matches("(SH|SZ)[0-9]{6}")))throw ComparisonErrors.invalid();return ok(service.options(stocks,period),req);}
 @PostMapping("/api/v1/comparisons") public ResponseEntity<ApiResponse<?>> create(Authentication auth,HttpServletRequest req){var user=owner(auth);query(req,Set.of());Input input;try{var bytes=req.getInputStream().readNBytes(2049);if(bytes.length>2048)throw new BusinessException("COMPARISON_REQUEST_TOO_LARGE","对比请求超过处理上限",HttpStatus.PAYLOAD_TOO_LARGE);var n=mapper.readTree(bytes);var names=new HashSet<String>();if(n==null||!n.isObject())throw ComparisonErrors.invalid();n.fieldNames().forEachRemaining(names::add);if(!names.equals(Set.of("requestId","instrumentIds","from","to","evidenceIds")))throw ComparisonErrors.invalid();var ids=strings(n.path("instrumentIds"));var versions=strings(n.path("evidenceIds")).stream().map(ComparisonRecords::uuid).toList();input=new Input(uuid(text(n,"requestId")),ids,LocalDate.parse(text(n,"from")),LocalDate.parse(text(n,"to")),versions);}catch(BusinessException e){throw e;}catch(Exception e){throw ComparisonErrors.invalid();}var c=service.create(user,input);var op=c.operation();HttpStatus status=op.state().equals("RUNNING")?HttpStatus.ACCEPTED:op.state().equals("FAILED")?HttpStatus.SERVICE_UNAVAILABLE:c.replayed()?HttpStatus.OK:HttpStatus.CREATED;if(op.state().equals("FAILED"))throw new BusinessException(op.errorCode(),"上次对比未完成，请查看原请求状态后重新计算",status);return ResponseEntity.status(status).body(ok(op,req));}
 @GetMapping("/api/v1/comparisons/operations/{id}") public ApiResponse<?> operation(Authentication auth,@PathVariable String id,HttpServletRequest req){query(req,Set.of());return ok(service.operation(owner(auth),uuid(id)),req);}
 @GetMapping("/api/v1/comparisons/{id}") public ApiResponse<?> get(Authentication auth,@PathVariable String id,HttpServletRequest req){query(req,Set.of());return ok(service.get(owner(auth),uuid(id)),req);}
 @GetMapping("/api/v1/comparisons") public ApiResponse<?> list(Authentication auth,HttpServletRequest req){query(req,Set.of("before","upper"));return ok(service.list(owner(auth),req.getParameter("before"),req.getParameter("upper")),req);}
 private List<String> strings(JsonNode n){if(!n.isArray()||n.size()<2||n.size()>3)throw ComparisonErrors.invalid();var result=new ArrayList<String>();for(var v:n){if(!v.isTextual()||v.asText().length()>64)throw ComparisonErrors.invalid();result.add(v.asText());}return result;}
 private String text(JsonNode n,String key){if(!n.path(key).isTextual())throw ComparisonErrors.invalid();return n.get(key).asText();}
 private void query(HttpServletRequest req,Set<String> allowed){if(!allowed.containsAll(req.getParameterMap().keySet())||req.getParameterMap().values().stream().anyMatch(v->v.length!=1))throw ComparisonErrors.invalid();}
 private UUID owner(Authentication auth){if(auth==null||!auth.isAuthenticated()||!(auth.getPrincipal() instanceof Actor actor))throw new BusinessException("AUTH_REQUIRED","请先登录",HttpStatus.UNAUTHORIZED);return actor.userId();}
 private ApiResponse<?> ok(Object data,HttpServletRequest req){return ApiResponse.success(data,TraceIds.normalize(req.getHeader("X-Trace-Id")));}
}
